  const submitDeal = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setBusy(true); setError(''); setMessage(''); const d = new FormData(event.currentTarget); const dateValue = (name: string) => { const value = String(d.get(name) || ''); return value ? new Date(value).toISOString() : null }; try { await post('/admin/deals', { id: d.get('id'), businessId: d.get('businessId'), title: d.get('title'), description: d.get('description'), channel: d.get('channel'), category: d.get('category'), restrictions: d.get('restrictions'), imageUrl: dealImage, promoCode: d.get('promoCode') || undefined, estimatedSavingsCents: Math.round(Number(d.get('estimatedSavingsCents') || 0) * 100), startsAt: dateValue('startsAt'), endsAt: dateValue('endsAt'), featured: d.get('featured') === 'on', sponsored: d.get('sponsored') === 'on', giveaway: d.get('giveaway') === 'on' }); event.currentTarget.reset(); setDealImage(null); setMessage('Deal published to Discover.'); await load() } catch (e) { setError((e as Error).message) } finally { setBusy(false) } }
